package com.fasterxml.jackson.core.io;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class NumberInput_parseBigDecimal_TriageGen1Test {

    @Test
    public void testParseBigDecimal_ValidInteger() throws NumberFormatException {
        String input = "123";
        BigDecimal expected = new BigDecimal("123");
        BigDecimal actual = NumberInput.parseBigDecimal(input);
        assertEquals(expected, actual);
    }

    @Test
    public void testParseBigDecimal_ValidDecimal() throws NumberFormatException {
        String input = "123.456";
        BigDecimal expected = new BigDecimal("123.456");
        BigDecimal actual = NumberInput.parseBigDecimal(input);
        assertEquals(expected, actual);
    }

    @Test
    public void testParseBigDecimal_NegativeValue() throws NumberFormatException {
        String input = "-456.78";
        BigDecimal expected = new BigDecimal("-456.78");
        BigDecimal actual = NumberInput.parseBigDecimal(input);
        assertEquals(expected, actual);
    }

    @Test
    public void testParseBigDecimal_ScientificNotation() throws NumberFormatException {
        String input = "1.23E4";
        BigDecimal expected = new BigDecimal("1.23E4");
        BigDecimal actual = NumberInput.parseBigDecimal(input);
        assertEquals(expected, actual);
    }

    @Test
    public void testParseBigDecimal_Zero() throws NumberFormatException {
        String input = "0";
        BigDecimal expected = BigDecimal.ZERO;
        BigDecimal actual = NumberInput.parseBigDecimal(input);
        assertEquals(expected, actual);
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_InvalidString() throws NumberFormatException {
        String input = "abc";
        NumberInput.parseBigDecimal(input);
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_EmptyString() throws NumberFormatException {
        String input = "";
        NumberInput.parseBigDecimal(input);
    }

    @Test(expected = NullPointerException.class)
    public void testParseBigDecimal_NullInput() throws NumberFormatException {
        String input = null;
        NumberInput.parseBigDecimal(input);
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_MalformedDecimal() throws NumberFormatException {
        String input = "123.45.67";
        NumberInput.parseBigDecimal(input);
    }
}
